import { addChildScene } from "./addChildScene";

export type OverlaySceneEntry = {
  key: string;
  parent: Phaser.Scene;
  childScene: Phaser.Scene;
  destroy: () => void;
};

export class OverlaySceneHost {
  private static readonly registry = new Map<string, OverlaySceneEntry>();

  static getOverlayScene(parentScene: Phaser.Scene, key?: string): OverlaySceneEntry {
    const entryKey = key ?? `overlay_${Date.now()}`;
    const existing = this.registry.get(entryKey);
    if (existing) return existing;

    const { childScene, destroy, childSceneKey } = addChildScene({
      scene: parentScene,
      childSceneKey: entryKey,
    });

    const entry: OverlaySceneEntry = {
      key: childSceneKey,
      parent: parentScene,
      childScene,
      destroy
    }
    this.registry.set(entryKey,entry);
    return entry;
  }

  static destroy(key: string): void {
    const entry = this.registry.get(key);
    if (!entry) return;
    entry.destroy();
    this.registry.delete(key);
  }
}
