import { IKlondikeCard, IKlondikeStackMap } from "../interfaces";
import { CardStackMover } from "../../cards-abstract";

interface VisionTricksProps {
  scene: Phaser.Scene;
  stacksMap: IKlondikeStackMap;
  cardStackMover: CardStackMover;
}

export class VisionTrick {
  state: {
    isDestroyed: boolean;
    trick: undefined | "vision" | "magic";
  } = {
    isDestroyed: false,
    trick: undefined,
  };

  constructor(private props: VisionTricksProps) {}

  destroy() {
    this.state.isDestroyed = true;
  }

  doVision({ durationMs }: { durationMs: number }): Promise<void> {
    return new Promise((resolve) => {
      if (this.state.trick || this.state.isDestroyed) {
        resolve();
        return;
      }

      const { stacksMap, scene } = this.props;
      const flippedCards: IKlondikeCard[] = [];
      this.state.trick = "vision";

      stacksMap.piles.forEach((pile) => {
        pile.cards.forEach((card) => {
          if (!card.isFaceUp) {
            this.flipCard(card, "face").catch(console.warn);
            flippedCards.push(card);
          }
        });
      });

      if (flippedCards.length === 0) {
        this.state.trick = undefined;
        resolve();
        return;
      }

      scene.time.delayedCall(durationMs, () => {
        if (this.state.isDestroyed) {
          resolve();
          return;
        }

        const flipBackPromises: Promise<void>[] = [];
        flippedCards.forEach((card) => {
          flipBackPromises.push(this.flipCard(card, "back"));
        });

        if (flipBackPromises.length > 0) {
          Promise.all(flipBackPromises)
            .catch(console.warn)
            .finally(() => {
              this.state.trick = undefined;
              resolve();
            });
        }
      });
    });
  }

  private flipCard(card: IKlondikeCard, side: "face" | "back") {
    return this.props.cardStackMover.do({
      isNotForHistory: true,
      flip: { cards: [card], duration: 350, side },
    });
  }
}
