import { getCardClassic52Deck, IClassicCardDto } from "../../../common";

/**
 * Временное состояние пасьянса
 * и на данный момент не должно сохраняться
 * **/
export interface IGameSessionState {
  score: number;
  timeMs: number;
  deckCards: IClassicCardDto[];
  isUndoPossible: boolean;
  isHintPossible: boolean;
  isMagicPossible: boolean;
  isVisionPossible: boolean;
}

export const getDefaultGameSession = ()=> ({
  score: 0,
  timeMs: 0,
  deckCards: getCardClassic52Deck().cards.all,
  isHintPossible: false,
  isMagicPossible: false,
  isUndoPossible: false,
  isVisionPossible: false
})
