import { CoreBehavior, SimpleGameSessionTimer } from "../../common/game-core";
import { GameEventsConnector } from "../../logic/events";
import { onScenePauseResume } from "../../common/scenes";

/** Таймер времени игровой сессии
 *  не имеет состояния
 *  todo - пауза при покупке или игровой паузе
 * **/
export class GameSessionTimerBehavior extends CoreBehavior {
  readonly type = "GameSessionTimerBehavior";

  create(scene: Phaser.Scene) {
    const events = new GameEventsConnector(scene);
    this.addUnSub(() => events.unSubscribeAll());

    const timer = new SimpleGameSessionTimer({
      scene,
      onTick: (currentSessionMs) => {
        events.emit("gameSessionTimerCurrentTimeMs", currentSessionMs);
      },
      onEnd: (currentSessionMs) => {
        events.emit("gameSessionTimerCurrentTimeMs", currentSessionMs);
      },
    });
    this.addUnSub(() => timer.stop());

    const onScenePauseResumeClearer = onScenePauseResume({ scene,
      onSwitch: (paused) => (paused ? timer.pause() : timer.resume())
    });

    this.addUnSub(onScenePauseResumeClearer);

    events.on("commandGameSessionTimer", (command) => {
      switch (command) {
        case "start":
          timer.start();
          break;
        case "stop":
          timer.stop();
          break;
        case "pause":
          timer.pause();
          break;
        case "resume":
          timer.resume();
          break;
        case "clear":
          timer.stopAndClear();
          break;
      }
    });
  }
}
