import {
  CardActionType,
  CardMovePart,
  CardMove,
  ICardFlipAction,
  ICardTranslateAction,
} from "../../cards-abstract";
import { IKlondikeCard, IKlondikeStack, IKlondikeStackMap, KlondikeStackType } from "../interfaces";

interface IProps {
  stacksMap: IKlondikeStackMap;
}

/**
 *  Смысл логики карточной игры
 *  в том чтобы подготовить команды
 *  и записать их в исполнение
 **/
export class KlondikeMoveLogic {
  constructor(protected props: IProps) {}

  /**
   * Вычислить последовательность ходов для раздачи
   **/
  dealCards(): CardMove[] {
    const { stacksMap } = this.props;
    const moves: CardMovePart[][] = [];
    const fromStack = stacksMap.deck;
    const piles = [...stacksMap.piles];
    const pilesAmount = piles.length;
    let dealCardIndex = 0;
    for (let row = 0; row < pilesAmount; row++) {
      for (let pileIndex = row; pileIndex < pilesAmount; pileIndex++) {
        // берем верхнюю карту из кладбища, не удаляя - удалять будет mover
        // внимание - критично сдвигать dealCardIndex
        const nextCard = fromStack.cards[dealCardIndex++];
        const toStack = piles[pileIndex];
        if (nextCard == null || toStack == null) continue;
        const commands: CardMovePart[] = [this.move(nextCard, fromStack, toStack)];
        /** верхние карты переворачиваем **/
        if (pileIndex === row) commands.push(this.flip(nextCard, "face"));
        moves.push(commands);
      }
    }
    return moves;
  }

  recycleDeck(): CardMove[] {
    const moves: CardMovePart[][] = [];
    const { deck, grave } = this.props.stacksMap;
    if (deck.length > 0 || grave.length === 0) return moves;
    const reversedGraveCards = [...grave.cards].reverse();

    reversedGraveCards.forEach((card, index) => {
      /** переворачиваем каждую карту и бросаем ее обратно в deck **/
      moves.push([this.flip(card, "back"), this.move(card, grave, deck)]);
    });
    return moves;
  }

  /**
   *  Групповой перенос карт
   *  если from - pile, то добавляется переворот верхней карты если она не закраты
   ***/
  moveBatch(
    cards: IKlondikeCard[],
    fromStack: IKlondikeStack,
    toStack: IKlondikeStack,
  ): CardMove {
    const batchAction: CardMovePart[] = [this.move(cards, fromStack, toStack)];

    if (fromStack.type === KlondikeStackType.PILE) {
      const nextCardFromTop = fromStack.cards[fromStack.cards.length - cards.length - 1];
      if(nextCardFromTop!=null && !nextCardFromTop.isFaceUp){
        batchAction.push(this.flip(nextCardFromTop, "face"));
      }
    }

    return batchAction;
  }

  /**
   * Флип перед переносом (используется для магии)
   */
  flipThenMoveBatch(
    card: IKlondikeCard,
    fromStack: IKlondikeStack,
    toStack: IKlondikeStack,
    side: "face" | "back",
  ): CardMove {
    return [this.flip(card, side), this.move(card, fromStack, toStack)];
  }

  /**
   * Одиночную карту с колоды вскрываем
   * - двигаем в сброс
   * - переворачиваем
   * **/
  openFromDeck(): CardMove | undefined {
    const { stacksMap } = this.props;
    const card = stacksMap.deck.pickTopCard();
    if (card == null) return;
    return [this.move(card, stacksMap.deck, stacksMap.grave), this.flip(card, "face")];
  }

  /** PRIVATE энкодеры команд **/
  private move(
    card: IKlondikeCard | IKlondikeCard[],
    fromStack: IKlondikeStack,
    toStack: IKlondikeStack,
  ): ICardTranslateAction {
    return {
      type: CardActionType.move,
      card,
      fromStack,
      toStack,
    };
  }

  private flip(card: IKlondikeCard, side: "face" | "back"): ICardFlipAction {
    return {
      type: CardActionType.flip,
      card,
      side,
    };
  }
}
