import { GameEventsConnector } from "../../logic";
import { KlondikeEventsEmitter } from "../../common";

export function mapKlondike2Game(scene: Phaser.Scene, klondikeEvents: KlondikeEventsEmitter) {
  const gameEvents = new GameEventsConnector(scene);
  const unSubs: Array<() => void> = [];

  /** klondikeEvents to gameEvents **/
  unSubs.push(klondikeEvents.on("onDealFinish", () => gameEvents.emit("klondikeOnDealFinish")));
  unSubs.push(klondikeEvents.on("showHint", () => gameEvents.emit("klondikeShowHint")));
  unSubs.push(klondikeEvents.on("undoCardMove", () => gameEvents.emit("klondikeUndoCardMove")));
  unSubs.push(klondikeEvents.on("undoCardMoveFinished", () => gameEvents.emit("klondikeUndoFinish")));
  unSubs.push(
    klondikeEvents.on("hintShown", (data) => {
      gameEvents.emit("klondikeHintShown", data);
    })
  );
  unSubs.push(
    klondikeEvents.on("cardMove", (data) => {
      gameEvents.emit("klondikeCardMove", data);
    })
  );
  unSubs.push(klondikeEvents.on("cardSound", () => gameEvents.emit("klondikeCardSound")));
  unSubs.push(
    klondikeEvents.on("cardAutoMoveFail", (data) => {
      gameEvents.emit("klondikeCardAutoMoveFail", data);
    })
  );

  /** gameEvents to klondikeEvents **/
  unSubs.push(gameEvents.on("doKlondikeUnDo", () => klondikeEvents.emit("undoCardMove")));
  unSubs.push(gameEvents.on("doKlondikeHint", () => klondikeEvents.emit("showHint")));
  unSubs.push(gameEvents.on("doKlondikeVision", (data) => klondikeEvents.emit("doVision", data)));
  unSubs.push(gameEvents.on("doKlondikeMagic", data => klondikeEvents.emit("doMagic", data)));

  return () => {
    unSubs.forEach((unSub) => unSub());
  };
}
