import { CoreBehavior } from "../../common/game-core";
import { gameStateStore, ISettingsState, SoundKey } from "../../logic";

/**
 *  Включает и выключает звуки по стейту настроек
 *  следит за состоянием и поднимает музыку после первого пользовательского клика
 **/
export class SoundSettingsBehavior extends CoreBehavior {
  readonly type = "SoundSettingsBehavior";
  private readonly musicVolume = 0.09;
  private isInputUnlocked = false;

  create(scene: Phaser.Scene) {
    const settings = gameStateStore.getStateConnector("settings");

    const onFirstPointer = () => {
      this.isInputUnlocked = true;
      this.applySound(settings.getState());
    };

    // Один раз ждём клика пользователя, чтобы можно было легально запустить музыку
    scene.input.once("pointerdown", onFirstPointer);

    this.applySound(settings.getState());
    this.addUnSub(settings.on((state) => this.applySound(state)));
  }

  /** Применяет состояние настроек к звукам/музыке */
  private applySound(state: ISettingsState) {
    this.scene.sound.mute = !state.isSoundOn;

    const soundOff = !state.isSoundOn;
    const musicOff = !state.isMusicOn;

    // если звук или музыка выключены — стопаем музыку и выходим
    if (soundOff || musicOff) {
      this.stopMusic();
      return;
    }

    // звук включён, музыка включена: запускаем/резюмим, если уже был клик
    if (this.isInputUnlocked) {
      this.playOrResumeMusic();
    }
  }


  /** Старт/резюм при активных флагах */
  private playOrResumeMusic() {
    try {
      const music = this.scene.sound.get(SoundKey.music) ?? this.scene.sound.add(SoundKey.music);

      if (music.isPlaying) return;
      if (music.isPaused) {
        music.resume();
        return;
      }
      music.play({ loop: true, volume: this.musicVolume });
    } catch (e) {
      console.warn(e);
    }
  }

  /** Останавливает музыку, если она есть */
  private stopMusic() {
    try {
      const music = this.scene.sound.get(SoundKey.music);
      if (!music) return;
      if (music.isPlaying || music.isPaused) {
        music.stop();
      }
    } catch (e) {
      console.warn(e);
    }
  }
}
