import { CoreBehavior } from "../../common/game-core";
import { GameEventsConnector, gameStateStore, getDefaultGameSession, IGameSessionState } from "../../logic";
import { shuffleArray, StateConnector } from "../../common";

/**
 *  Ядро запуска игры
 *  без него не стартует пасьянс
 ***/
export class CoreGameSessionBehavior extends CoreBehavior {
  readonly type = "CoreGameSessionBehavior";
  protected gameEvents: GameEventsConnector | undefined;
  protected session: StateConnector<IGameSessionState> | undefined;

  create(scene: Phaser.Scene) {
    this.gameEvents = new GameEventsConnector(scene);
    this.session = gameStateStore.getStateConnector("gameSession");
    this.addUnSub(() => this.gameEvents?.unSubscribeAll());
    this.addUnSub(() => this.session?.unSubScribeAll());

    this.initState({ isNewCards: true });

    /** bind gameEvents **/
    this.gameEvents.on("onNewGameButtonClick", () => {
      this.initState({ isNewCards: true });
      this.restartSession();
    });
    this.gameEvents.on("onReplayGameButtonClick", () => {
      this.initState({ isNewCards: false });
      this.restartSession();
    });

    this.gameEvents.on("gameSessionTimerCurrentTimeMs", (timeMs) => {
      this.session?.setState((prev) => ({ ...prev, timeMs }));
    });

    this.gameEvents.on("klondikeOnDealFinish", () => {
      this.gameEvents?.emit("commandGameSessionTimer", "start");
    });

    this.gameEvents.on("klondikeStateUpdate", state => {
      this.session?.setState(prev=>({
        ...prev,
        ...state
      }))
    });


    /******** START GAME **********/
    this.restartSession();
  }

  private initState({ isNewCards }: { isNewCards?: boolean }) {
    const { session } = this;
    if (!session) {
      console.warn("CoreGameSessionBehavior - session is not initialized");
      return;
    }
    const prevCards = session.getState().deckCards;
    const cards = isNewCards ? shuffleArray(prevCards) : prevCards;
    this.session?.setState({ ...getDefaultGameSession(), deckCards: cards });
  }

  private restartSession() {
    const cards = this.session?.getState().deckCards;
    if (!cards) {
      console.warn("CoreGameSessionBehavior - session is not initialized");
      return;
    }
    this.gameEvents?.emit("commandGameSessionTimer", "clear");
    this.gameEvents?.emit("gameViewStartKlondike", { cards });
  }
}
