import { Scenes } from "../../common/game-core";
import { GameSceneView } from "./GameSceneView";
import { GameSceneBehaviors } from "./GameSceneBehaviors";

export class GameScene extends Phaser.Scene {
  constructor() {
    super(Scenes.Game);
  }

  preload() {}

  create() {
    const scene = this;
    new GameSceneView(scene);
    new GameSceneBehaviors(this);
  }
}
