/** Товар который продаем **/
export interface IGoody<Id extends string = string> {
  id: Id;
  amount: number;
}

export enum ShopCurrency {
  /** показ рекламы **/
  REWARD_AD = "REWARD_AD",
  /** премиум валюта - YAN в Яндексе и тд  **/
  PREMIUM_GOLD = "PREMIUM_GOLD",
}

/**
 * что выставляется в магазине
 * - может быть несколько товаров
 * **/
export interface IShopItem<Id extends string = string, GoodyId extends string = string> {
  /** id - всегда id именно текущего объекта **/
  id: Id;
  /** товары **/
  goody: IGoody<GoodyId>[];
  /** цена **/
  price: number;
  currency: ShopCurrency;
}
