import { Info } from "./Info";
import { getHhMmSs } from "../../../../common";

interface IProps {
  scene: Phaser.Scene;
  timeMs: number;
  timePrefix: string;
  bgBuilder: (w: number, h: number) => Phaser.GameObjects.NineSlice;
  textBuilder: (text: string) => Phaser.GameObjects.Text;
}

/** Информационные табло - текст и фон **/
export class GameSessionTimeInfo extends Info {
  protected timePrefix: string;

  constructor({ timePrefix, timeMs, ...props }: IProps) {
    super({
      initText: "",
      ...props,
    });
    this.timePrefix = timePrefix;
    this.setTime(timeMs);
  }

  setTime(timeMs: number) {
    const maxLimit = 1000 * 60 * 59 + 59 * 1000;
    const ms = Math.min(maxLimit, timeMs);
    const text = `${this.timePrefix} ${getHhMmSs(ms)}`;
    this.setText(text);
  }
}
