import { StartView } from "./StartView";
import { Scenes } from "../../common/game-core";
import { SoundSettingsBehavior } from "../../behaviors/soundSettings/SoundSettingsBehavior";
import { SettingsBehavior } from "../../behaviors/settings/SettingsBehavior";

export class StartScene extends Phaser.Scene {
  constructor() {
    super(Scenes.Start);
  }

  preload() {}

  create() {
    const scene = this;
    const behaviors = [
      SoundSettingsBehavior.enable(scene, true),
      SettingsBehavior.enable(scene, true),
    ];

    new StartView({ scene });
  }
}
