import { IKlondikeCard, IKlondikeStack, KlondikeStackType } from "../interfaces";
import { IKlondikeScoreCounter, IScoreCounterMoveProps } from "./types";

export class ClassicRussianKlondikeScoreCounter implements IKlondikeScoreCounter {
  public readonly name = "ClassicRussianKlondikeScoreCounter";

  public scoreDeckRecycle(): number {
    return -20;
  }

  public scoreMove({ card, fromStack, toStack }: IScoreCounterMoveProps): number {
    let score = 0;
    const fromType = fromStack.type;
    const toType = toStack?.type;

    // Открытие карты на столе
    if (this.doesMoveOpenHiddenCard(card, fromStack)) {
      score += 5;
    }

    // Из колоды/сброса на стол
    if (
      (fromType === KlondikeStackType.DECK || fromType === KlondikeStackType.GRAVE) &&
      toType === KlondikeStackType.PILE
    ) {
      score += 5;
    }

    // Отдельно учитываем клик по колоде (DECK без toStack)
    if (fromType === KlondikeStackType.DECK && toType == null) {
      score += 5;
    }

    // Перемещение в дом
    if (toType === KlondikeStackType.BASE) {
      score += 10;
    }

    // Прокрутка колоды
    if (toType === KlondikeStackType.DECK) {
      score -= 20;
    }

    // Возврат из дома на стол
    if (fromType === KlondikeStackType.BASE && toType === KlondikeStackType.PILE) {
      score -= 15;
    }

    return score;
  }

  // Проверяет, откроет ли перенос карты скрытую карту под ней в исходной стопке
  private doesMoveOpenHiddenCard(card: IKlondikeCard, fromStack: IKlondikeStack): boolean {
    const index = fromStack.cards.indexOf(card);
    const isLastCard = index <= 0;
    if (isLastCard) {
      return false;
    }
    const belowCard = fromStack.cards[index - 1];
    return belowCard != null && !belowCard.isFaceUp;
  }
}
