import { PlayerDataSnapshot, SettingsSnapshot } from "./types";

/**
 * Хранилище данных игрока с lazy-синглтоном.
 * Реальная загрузка/сохранение может быть переподключена (локальное хранилище, сервер и т.п.).
 */
export class PlayerDataService {
  private static instance: PlayerDataService | undefined;

  /** Кеш последней успешной загрузки. */
  private cache: PlayerDataSnapshot | undefined;

  private state = {
    isLoading: false
  };

  /** Ленивая выдача инстанса. */
  static getInstance(): PlayerDataService {
    if (!PlayerDataService.instance) {
      PlayerDataService.instance = new PlayerDataService();
    }
    return PlayerDataService.instance;
  }

  /** Сбросить синглтон (для тестов/сторибука). */
  static resetInstance() {
    PlayerDataService.instance = undefined;
  }

  private constructor() {
  }

  /**
   * Асинхронная предварительная загрузка данных игрока.
   * Повторные вызовы до завершения вернут тот же promise.
   */
  async preload(): Promise<PlayerDataSnapshot | undefined> {
    if (this.state.isLoading) return;
    try {
      this.state.isLoading = true;
      this.cache = await this.loadFromStorage();
    } catch (e) {
      console.warn(e);
    }
    this.state.isLoading = false;
    return this.cache;
  }

  /**
   * Синхронное чтение последнего снэпшота.
   * Если данных еще не было, возвращает undefined.
   */
  getSnapshot(): PlayerDataSnapshot | undefined {
    return this.cache;
  }

  /**
   * Асинхронное сохранение нового снэпшота.
   * При успехе обновляет кеш.
   */
  async save(snapshot: PlayerDataSnapshot): Promise<void> {
    await this.saveToStorage(snapshot);
    this.cache = snapshot;
  }

  /** Заглушка загрузки — подменить на реальное хранилище. */
  private async loadFromStorage(): Promise<PlayerDataSnapshot> {
    // TODO: подключить конкретное хранилище (localStorage / backend / SDK).
    return {
      consumables: {
        undo: 3,
        hint: 3,
        vision: 3,
        magic: 3
      },
      settings: this.getDefaultSettings(),
      version: 1
    };
  }

  /** Заглушка сохранения — подменить на реальное хранилище. */
  private async saveToStorage(snapshot: PlayerDataSnapshot): Promise<void> {
    // TODO: подключить конкретное хранилище (localStorage / backend / SDK).
    void snapshot;
  }

  getDefaultSettings(): SettingsSnapshot {
    return {
      isMusicOn: true,
      isSoundOn: true,
      locale: "ru",
    };
  }
}
