import { IKlondikeCard } from "./interfaces";

interface IDragStateLike {
  clickedCard: IKlondikeCard;
  startPositions: Map<IKlondikeCard, { x: number; y: number }>;
}

/**
 * Проверяет, превысил ли драг минимальный порог.
 * Возвращает false, если нет стартовой позиции.
 */
export function hasMinimalDragOffset(dragState: IDragStateLike, threshold: number): boolean {
  const start = dragState.startPositions.get(dragState.clickedCard);
  if (!start) return false;
  const dx = dragState.clickedCard.x - start.x;
  const dy = dragState.clickedCard.y - start.y;
  return dx * dx + dy * dy >= threshold * threshold;
}
