import { State } from "../../../events";
import { KlondikeSolitaireRules } from "../KlondikeSolitaireRules";
import { IKlondikeCard, IKlondikeStack, IKlondikeStackMap, KlondikeStackType } from "../interfaces";
import { IKlondikeScoreCounter } from "../score";

interface HintTrickProps {
  stacksMap: IKlondikeStackMap;
  scoreCounter: IKlondikeScoreCounter;
}

export class HintTrick {
  state: {
    isDestroyed: boolean;
    trick: undefined | "hint";
  } = {
    isDestroyed: false,
    trick: undefined,
  };

  /** живое состояние подсказки */
  liveState = new State<{ hintCard?: IKlondikeCard }>({ hintCard: undefined });

  private readonly rules = new KlondikeSolitaireRules();

  constructor(protected props: HintTrickProps) {}

  /** Очистка ресурсов трюка */
  destroy() {
    this.state.isDestroyed = true;
    this.liveState.unSubScribeAll();
  }

  /** Обновляет liveState подсказки */
  updateLiveState() {
    this.liveState.setState({ hintCard: this.getHintCard() });
  }

  /**
   * Обновляет и возвращает подходящую карту для подсказки.
   */
  private getHintCard(): IKlondikeCard | undefined {
    /** ищем лучшую подсказку среди всех стаков */
    const card = this.findHint({
      fromStacks: [
        this.props.stacksMap.grave,
        ...this.props.stacksMap.piles,
        this.props.stacksMap.deck,
      ],
      toStacks: [...this.props.stacksMap.piles, ...this.props.stacksMap.bases],
    });

    this.liveState.setState({ hintCard: card });
    return card;
  }

  private findHint({
    fromStacks,
    toStacks,
  }: {
    fromStacks: IKlondikeStack[];
    toStacks: IKlondikeStack[];
  }) {
    const { rules } = this;
    let bestCard: IKlondikeCard | undefined;
    let bestScore = -Infinity;

    for (const fromStack of fromStacks) {
      const card = fromStack.topCard;
      if (card == null) continue;

      const fromDeck = fromStack.type === KlondikeStackType.DECK;
      let deckCandidateChecked = false;

      for (const toStack of toStacks) {
        if (rules.isDroppable(card, toStack)) continue;
        /** считаем очки хода и выбираем лучший */
        const score = this.props.scoreCounter.scoreMove({ card, fromStack, toStack });
        if (score > bestScore) {
          bestScore = score;
          bestCard = card;
        }
      }

      /** отдельный кандидат для клика по колоде */
      if (fromDeck && !deckCandidateChecked) {
        const score = this.props.scoreCounter.scoreMove({ card, fromStack });
        deckCandidateChecked = true;
        if (score > bestScore) {
          bestScore = score;
          bestCard = card;
        }
      }
    }

    /** если нет полезных ходов — подсказки нет */
    if (bestScore <= 0) {
      return undefined;
    }

    return bestCard;
  }
}
